class UpdateWatchRequest(VaquillModel):
    email_address: Annotated[
        str | None,
        Field(
            alias="emailAddress",
            description="New email address. Only valid on an email/both channel watch. Cannot be cleared.",
            title="Emailaddress",
        ),
    ] = None
    is_active: Annotated[
        bool | None,
        Field(
            alias="isActive",
            description="Pause (false) or resume (true) the watch.",
            title="Isactive",
        ),
    ] = None
    scope: Annotated[
        dict[str, str] | None,
        Field(
            description='Optional narrowing so this alert covers one citation instead of an entire source. Four mutually exclusive forms.\n\n**Hierarchy prefix** -- keys `title`, `chapter`, `part`, `section`, e.g. `{"title": "21", "part": "314"}` for 21 CFR part 314. Every level you set must match, so each one narrows further. `title` is required whenever any narrower level is set, and `section` also needs `chapter` or `part`: a bare part number matches across unrelated titles. Only sources whose documents carry a title/chapter/part hierarchy accept this form; the rest return 400.\n\n**Exact section** -- `{"actId": "CFR_T21_P314_S314_50"}`, using the `actId` returned by search results and change events. Case-sensitive, and validated at create time against the corpus: an act_id we do not hold, or one belonging to a different source, is a 400 rather than a watch that could never fire. This form works on EVERY source, including flat ones with no hierarchy, so it is the only way to follow a single Federal Register document.\n\n**Named source** -- `{"source": "fdic_fil"}`, for the corpora that fold several independent bodies of law behind one `corpusType`. The `agency_guidance` board alone carries 47 named sources across 24 agencies, so an unscoped watch on it delivers FDIC letters, IRS notices, OFAC FAQs and DOE appliance standards together. Accepted on `agency_adjudication`, `agency_guidance`, `agency_manuals`, `cfr`, `federal_rules`; anything else returns 400. The pickable values for a given board are on that board\'s `sources` array in `GET /boards` -- deliberately narrower than the `source` filter published on `POST /us/statutes/search`, because `agency_guidance` and `agency_manuals` are two boards reading one `corpusType` and each emits only its own half.\n\n**Publishing agency** -- `{"agency": "irs"}`, covering every source that agency issues on the board. `source` is the unit we ingest and it is finer than the unit most callers think in: the IRS alone publishes 5 named series, so following it by source means one watch per series and a gap if you miss one. An agency scope is expanded WHEN AN EVENT IS MATCHED rather than when the watch is created, so a source registered after your watch is covered by it automatically, with no action from you. Accepted on `agency_adjudication`, `agency_guidance`, `agency_manuals`; the pickable values are on that board\'s `agencies` array in `GET /boards`.\n\nOmit entirely to watch the whole source, which is the default and the pre-existing behavior.',
            examples=[{"part": "314", "title": "21"}],
            title="Scope",
        ),
    ] = None
    webhook_auth: Annotated[
        WebhookAuthRequest | None,
        Field(
            alias="webhookAuth",
            description='Replace the outbound credential config. Sent as a whole object, not field by field: a scheme without a credential is not a partial edit, it is a broken config. Send `{"scheme": "none"}` to remove auth entirely. Keeping the same scheme and omitting `secret` retains the stored credential, so you can rename a header without re-entering the token.',
        ),
    ] = None
    webhook_secret: Annotated[
        str | None,
        Field(
            alias="webhookSecret",
            description="New signing secret, or empty string to stop signing deliveries. Only valid on a webhook/both channel watch.",
            title="Webhooksecret",
        ),
    ] = None
    webhook_url: Annotated[
        str | None,
        Field(
            alias="webhookUrl",
            description="New webhook URL. Only valid on a webhook/both channel watch. Re-validated against the SSRF blocklist. Cannot be cleared.",
            title="Webhookurl",
        ),
    ] = None


class UsJurisdictionCoverage(VaquillModel):
    code: Annotated[
        str,
        Field(
            description="2-letter state ISO code (lowercase) or `federal` for USC/CFR.",
            examples=["tx"],
            title="Code",
        ),
    ]
    corpora: Annotated[
        dict[str, int] | None,
        Field(
            description='Per-corpusType ingested-DOCUMENT counts for this jurisdiction, keyed by the `corpusType` token (e.g. `{"STATE": 176778, "REGULATION": 51142}`). Only corpora with data are included. Pass a key as `corpusType` to `/us/statutes/search` to scope a query.',
            title="Corpora",
        ),
    ] = None
    has_data: Annotated[
        bool, Field(alias="hasData", description="True when section_count > 0.", title="Hasdata")
    ]
    kind: Annotated[
        Annotated[UsJurisdictionCoverageKind | str, lenient_validator(UsJurisdictionCoverageKind)],
        Field(
            description="`federal` for USC/CFR, `state` for the 50 states, `territory` for non-state jurisdictions (DC, Puerto Rico).",
            title="Kind",
        ),
    ]
    name: Annotated[str, Field(description="Display name.", examples=["Texas"], title="Name")]
    section_count: Annotated[
        int,
        Field(
            alias="sectionCount",
            description="Distinct sections held for this jurisdiction, summed across its `corpora`. 0 means not yet covered.\n\nOne per provision or document, NOT per retrieval passage (see `totalPassages` for those). Repealed, transferred and reserved sections ARE counted: a legal research corpus serves them and a customer researching a historical question needs them. A SUPERSEDED prior version is not counted a second time when the section it supersedes is also served, because that is the same section twice -- but one with no current counterpart IS counted, since it is the only text we hold for that provision. Read `statusBreakdown` to see the split.",
            title="Sectioncount",
        ),
    ]
    session_laws: Annotated[
        SessionLawJurisdictionCoverage | None,
        Field(
            alias="sessionLaws",
            description="State session laws (acts as enacted) held for this jurisdiction, by legislative session, with each session's coverage status (`complete` or `partial`), how many laws we serve, withhold or know without text, the expected total (`denominator`), `openGaps` and when it was `measuredAt`. Beside the sessions it carries the `series` and `instrumentTypes` that exist (the values `GET /us/session-laws/list` accepts) and the span of approval dates held (`earliestApprovedDate`, `latestApprovedDate`); each of those four is omitted when it cannot be read. A separate corpus: read and list the laws with `/us/session-laws`, not `/us/statutes/search`, and resolve their citations with `/us/statutes/resolve`. The whole block is absent when we hold no session laws for the jurisdiction, and whenever session-law coverage cannot be read; absence is a gap in our collection, not a statement that the jurisdiction enacts none.",
        ),
    ] = None
    status_breakdown: Annotated[
        dict[str, dict[str, int]] | None,
        Field(
            alias="statusBreakdown",
            description='Per-corpusType `act_status` split over the same sections `corpora` counts, e.g. `{"REGULATION": {"inForce": 12151, "repealed": 10640, "transferred": 5426}}`.\n\nPublished so a large section count can be read as maintained law plus retained history rather than as an undifferentiated total: Montana holds 28,217 regulation sections of which 12,151 are in force, and without this split that reads either as 28,217 current rules or as a coverage problem, and it is neither.\n\n⚠️ `inForce` is what the ingester recorded, and it is NOT a complete census of current law: a zero means the status was never determined, never that the corpus is entirely inoperative. It is the status recorded for the section; the currency verdict is `goodLawStatus` on each section, which is `unknown` where a jurisdiction does not publish repeal information. The `unknown` key counts sections whose status is not stated. Absent when a jurisdiction has not been measured exactly.',
            title="Statusbreakdown",
        ),
    ] = None


